<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>卡密验证系统</title><link rel="stylesheet" href="/layui.css"><style>.layui-layout-admin .layui-side{width:220px}.layui-layout-admin .layui-body{left:220px;background:#f6f7fb}.layui-side-scroll{width:240px}.page{display:none;padding:24px}.page.active{display:block}.metric{padding:20px}.metric b{font-size:30px;display:block;margin-top:8px}.muted{color:#8b95a7}.toolbar{display:flex;gap:10px;margin-bottom:14px}.key{font-family:Consolas,monospace}.layui-table-cell{height:auto;line-height:30px}.toast{position:fixed;right:28px;bottom:28px;z-index:3000}</style></head><body class="layui-layout-body"><div class="layui-layout layui-layout-admin"><div class="layui-header"><div class="layui-logo">卡密验证系统</div><ul class="layui-nav layui-layout-right"><li class="layui-nav-item"><a href="javascript:;">管理员</a></li></ul></div><div class="layui-side layui-bg-black"><div class="layui-side-scroll"><ul class="layui-nav layui-nav-tree" lay-filter="nav"><li class="layui-nav-item layui-this"><a href="javascript:" data-view="overview"><i class="layui-icon layui-icon-home"></i> 总览</a></li><li class="layui-nav-item"><a href="javascript:" data-view="licenses"><i class="layui-icon layui-icon-key"></i> 卡密管理</a></li><li class="layui-nav-item"><a href="javascript:" data-view="devices"><i class="layui-icon layui-icon-console"></i> 设备管理</a></li><li class="layui-nav-item"><a href="javascript:" data-view="logs"><i class="layui-icon layui-icon-list"></i> 审计日志</a></li></ul></div></div><div class="layui-body"><section id="overview" class="page active"><div class="layui-row layui-col-space16" id="metrics"></div><div class="layui-row layui-col-space16"><div class="layui-col-md6"><div class="layui-card"><div class="layui-card-header">最近授权</div><div class="layui-card-body" id="recentLic"></div></div></div><div class="layui-col-md6"><div class="layui-card"><div class="layui-card-header">最近审计事件</div><div class="layui-card-body" id="recentLogs"></div></div></div></div></section><section id="licenses" class="page"><div class="layui-card"><div class="layui-card-header">卡密管理 <button class="layui-btn layui-btn-sm layui-btn-normal" style="float:right;margin-top:8px" onclick="openCreate()"><i class="layui-icon layui-icon-add-1"></i> 批量生成</button></div><div class="layui-card-body"><div class="toolbar"><input id="search" class="layui-input" style="width:240px" placeholder="搜索卡密或产品" oninput="renderLicenses()"><select id="status" class="layui-select" onchange="renderLicenses()"><option value="">全部状态</option><option>issued</option><option>active</option><option>suspended</option><option>revoked</option></select><button class="layui-btn layui-btn-primary" onclick="exportKeys()">导出 CSV</button><button class="layui-btn layui-btn-danger" onclick="bulkDelete()">删除选中</button></div><table class="layui-table"><thead><tr><th><input type="checkbox" onchange="checkAll(this)"></th><th>完整卡密</th><th>产品</th><th>状态</th><th>设备上限</th><th>到期时间</th><th>创建时间</th><th>操作</th></tr></thead><tbody id="licenseRows"></tbody></table></div></div></section><section id="devices" class="page"><div class="layui-card"><div class="layui-card-header">设备管理</div><div class="layui-card-body"><table class="layui-table"><thead><tr><th>卡密前缀</th><th>设备名称</th><th>状态</th><th>最后验证</th></tr></thead><tbody id="deviceRows"></tbody></table></div></div></section><section id="logs" class="page"><div class="layui-card"><div class="layui-card-header">审计日志</div><div class="layui-card-body"><table class="layui-table"><thead><tr><th>动作</th><th>结果</th><th>原因</th><th>时间</th></tr></thead><tbody id="logRows"></tbody></table></div></div></section></div></div><script src="/layui.js"></script><script>const data=<?= $admin_data ?>;const esc=s=>String(s??'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));const fmt=v=>{if(!v)return'永久';let d=new Date(v),p=n=>String(n).padStart(2,'0');return isNaN(d)?v:`${d.getFullYear()}-${p(d.getMonth()+1)}-${p(d.getDate())} ${p(d.getHours())}:${p(d.getMinutes())}`};const badge=s=>`<span class="layui-badge ${s==='active'?'layui-bg-green':s==='issued'?'layui-bg-gray':'layui-bg-red'}">${s}</span>`;function show(v){document.querySelectorAll('.page').forEach(x=>x.classList.toggle('active',x.id===v));location.hash=v}function notice(t){layui.layer.msg(t,{time:3000,icon:1})}layui.use(['element','layer','form'],()=>{document.querySelectorAll('[data-view]').forEach(a=>a.onclick=()=>show(a.dataset.view));show(location.hash.slice(1)||'overview');render()});function render(){metrics.innerHTML=[['授权总数',data.licenses.length],['活跃授权',data.licenses.filter(x=>x.status==='active').length],['绑定设备',data.devices.length],['审计事件',data.logs.length]].map(x=>`<div class="layui-col-md3"><div class="layui-card metric"><span class="muted">${x[0]}</span><b>${x[1]}</b></div></div>`).join('');recentLic.innerHTML=data.licenses.slice(0,6).map(x=>`<p>${esc(x.key_prefix)}... ${badge(x.status)}</p>`).join('')||'暂无数据';recentLogs.innerHTML=data.logs.slice(0,6).map(x=>`<p>${esc(x.action)} <span class="muted">${fmt(x.created_at)}</span></p>`).join('')||'暂无数据';deviceRows.innerHTML=data.devices.map(x=>`<tr><td>${esc(x.key_prefix)}</td><td>${esc(x.device_name)}</td><td>${badge(x.status)}</td><td>${fmt(x.last_seen_at)}</td></tr>`).join('');logRows.innerHTML=data.logs.map(x=>`<tr><td>${esc(x.action)}</td><td>${esc(x.result)}</td><td>${esc(x.reason)}</td><td>${fmt(x.created_at)}</td></tr>`).join('');renderLicenses()}function renderLicenses(){let q=(search.value||'').toLowerCase(),s=status.value;licenseRows.innerHTML=data.licenses.filter(x=>(!q||x.plain_key?.toLowerCase().includes(q)||x.product_code.toLowerCase().includes(q))&&(!s||x.status===s)).map(x=>`<tr><td><input class="keyCheck" type="checkbox" value="${x.id}"></td><td class="key">${esc(x.plain_key||'历史卡密不可恢复')} ${x.plain_key?`<button class="layui-btn layui-btn-xs layui-btn-primary" onclick="copyKey('${x.plain_key}')">复制</button>`:''}</td><td>${esc(x.product_code)}</td><td>${badge(x.status)}</td><td>${x.max_devices}</td><td>${fmt(x.expires_at)}</td><td>${fmt(x.created_at)}</td><td><button class="layui-btn layui-btn-xs layui-btn-danger" onclick="removeKey('${x.id}')">删除</button></td></tr>`).join('')||'<tr><td colspan="8" class="muted">没有匹配的卡密</td></tr>'}function checkAll(x){document.querySelectorAll('.keyCheck').forEach(y=>y.checked=x.checked)}function copyKey(k){navigator.clipboard.writeText(k).then(()=>notice('已复制完整卡密'))}function exportKeys(){location.href='/admin/licenses/export'}async function removeKey(id){if(!confirm('确认删除？'))return;await fetch('/admin/licenses/'+id,{method:'DELETE'});location.reload()}async function bulkDelete(){let ids=[...document.querySelectorAll('.keyCheck:checked')].map(x=>x.value);if(!ids.length)return layui.layer.msg('请勾选卡密');if(!confirm(`确认删除 ${ids.length} 个卡密？`))return;await fetch('/admin/licenses/bulk-delete',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({ids})});location.reload()}function openCreate(){layui.layer.open({type:1,title:'批量生成卡密',area:['440px','auto'],content:`<form class="layui-form" style="padding:22px" id="createForm"><div class="layui-form-item"><label class="layui-form-label">产品编号</label><div class="layui-input-block"><input id="product" class="layui-input" value="debug"></div></div><div class="layui-form-item"><label class="layui-form-label">数量</label><div class="layui-input-block"><input id="count" type="number" class="layui-input" value="1" min="1" max="1000"></div></div><div class="layui-form-item"><label class="layui-form-label">设备上限</label><div class="layui-input-block"><input id="max" type="number" class="layui-input" value="1" min="1"></div></div><div class="layui-form-item"><label class="layui-form-label">到期策略</label><div class="layui-input-block"><select id="expiry" class="layui-input" onchange="custom.style.display=this.value==='custom'?'block':'none'"><option value="forever">永久</option><option value="hour">1 小时</option><option value="day">1 天</option><option value="week">1 周</option><option value="month">1 个月</option><option value="quarter">一季度</option><option value="year">1 年</option><option value="custom">自定义</option></select></div></div><div id="custom" style="display:none" class="layui-form-item"><label class="layui-form-label">到期时间</label><div class="layui-input-block"><input id="customTime" type="datetime-local" class="layui-input"></div></div><button type="button" class="layui-btn layui-btn-fluid" onclick="createKeys()">确认生成</button></form>`})}function expiry(){let v=document.querySelector('#expiry').value;if(v==='forever')return null;if(v==='custom')return new Date(customTime.value).toISOString();let n={hour:36e5,day:864e5,week:6048e5,month:2592e6,quarter:7776e6,year:31536e6}[v];return new Date(Date.now()+n).toISOString()}async function createKeys(){let r=await fetch('/admin/licenses',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({count:+count.value,product_code:product.value,max_devices:+max.value,expires_at:expiry()})}),j=await r.json();layui.layer.closeAll();if(j.licenses){notice('卡密生成成功');setTimeout(()=>location.reload(),350)}};</script></body></html>
